#define PI 3.14159
#define TAU 6.28318
#define OBJ_GROUP_0 0
#define OBJ_GROUP_1 1
#define OBJ_GROUP_2 2
#define OBJ_GROUP_3 3
float rand(float seed) {
    return fract(sin(seed)*100000.0);
}
mat2 rot2D(float angle) {
    float c = cos(angle);
    float s = sin(angle);

    return mat2(c, -s, s, c);
}

vec3 proj(vec3 u, vec3 v) {
    return v*(dot(u, v)/ dot(v, v));
}

//Signed distance & smooth union from Inigo Quilez
float sdSphere( vec3 ray, float size ) {
  return length(ray)-size;
}

float sdBox( vec3 ray, vec3 dimensions ) {
  vec3 q = abs(ray) - dimensions;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdPlane( vec3 ray, vec3 normal, float height ) {
  normal = normalize(normal);
  return dot(ray,normal) + height;
}


float opSmoothUnion( float d1, float d2, float k ) {
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float hash11(float x) {
    x = fract(x * 0.61803398875);
    x *= x;
    return fract(x * 43758.5453123);
}

vec2 hash22(vec2 p) {
    p = fract(p * vec2(0.1031, 0.11369));
    p += dot(p, p.yx + vec2(33.33, 71.17));
    return fract(sin(p) * vec2(43758.5453123, 22578.1459123));
}

vec3 fbmWave(vec2 uv, int n, float t) {
    float ampFact = 0.912421;
    float freqFact = 1.21232;
    float amp = 1.0;
    float freq = 0.9;
    vec3 derivative = vec3(0.0);

    for (int i = 0; i < n; i++) {
        amp *= ampFact;
        freq *= freqFact;
        vec2 ruv = uv;
        ruv *= rot2D(hash11(float(i)) * TAU);

        float g = ruv.x * freq * 30.0 + ruv.y * freq * 30.0 + t;
        float sinG = sin(g);
        float cosG = cos(g);

        vec2 gradG = vec2(freq * 30.0 * rot2D(hash11(float(i)) * TAU));

        vec3 cDerivative = amp*vec3(-amp * cosG * gradG.x, 60., -amp * cosG * gradG.y);

        derivative += cDerivative;
        uv += cDerivative.xz*0.0003*amp;
    }

    return normalize(derivative);
}

//Object definition
float getDist(vec3 ray, float t) {
    vec3 r1 = ray;
    vec3 r2 = ray;

    ray.z -= .5 +sin(ray.x + ray.z*0.01);
    ray = fract(ray) -.5;

    r1.x -= cos(r1.z*.1 + r1.x*0.001);
    r1 = fract(r1) - .5;

    r2.y -= 0.5+sin(r2.x);
    r2.x -= cos(r2.z*0.1 + r2.x*0.001);
    r2 = fract(r2) - .5;

    float d1 = sdSphere(ray, 0.3);
    float d2 = sdSphere(r1, 0.2);
    float d3 = sdSphere(r2, 0.1);

    float d = opSmoothUnion( d1, d2, .5);
    d = opSmoothUnion( d, d3, .4);
    return d;  
}
float getWaterDist(vec3 ray) {
    return sdPlane(ray, vec3(0., 1., 0.), .1);
}

//From Art of Code
vec3 getNormal(vec3 p, float t) {
    vec2 e = vec2(.001, 0);
    vec3 n = getDist(p, t) - 
        vec3(getDist(p-e.xyy, t), getDist(p-e.yxy, t),getDist(p-e.yyx, t));

    return normalize(n);
}

// textures objeccts based on ray
vec3 textureObj(vec3 ray, float t) {
    vec3 colXZ;
    vec3 colXY;
    vec3 colYZ;

    colXZ = texture(iChannel0, ray.xz * 0.25 + 0.5).rgb;
    colXY = texture(iChannel0, ray.xy * 0.5 + 0.5).rgb;
    colYZ = texture(iChannel0, ray.yz * 0.5 + 0.5).rgb;

    vec3 normal = getNormal(ray, t);

    return colXZ * clamp(-normal.y, 0., 1.) + colXY * abs(normal.z) + colYZ * abs(normal.x);
}

vec3 textureWater(vec3 waveDerivative, float t) {
    vec3 colXZ;

    vec3 sunPos = normalize(vec3(0., 1., 1.));
    float diffuseFact = clamp(dot(sunPos, waveDerivative), 0., 1.);
    vec3 diffuseCol = vec3(0.651, 0.392, 0.332);
    vec3 ambientCol = vec3(0.3, 0.1, 0.05);
    colXZ = mix(ambientCol, diffuseCol, diffuseFact);

    return colXZ;
}
//Returns colour of object
vec3 raymarch(vec3 origin, vec3 ray, float t) {
    float totDist = 0.0;
    int iterations = 0;
    vec3 colour = vec3(0.0);
    float waterFact = 1.;
    bool checkWater = true;
    vec3 pos = origin;
    for (int i = 0; i < 256; i++) {
        iterations++;
        float dist = getDist(pos, t);
        float waterDist = 100.;
        if (checkWater) {
            waterDist = getWaterDist(pos);
        }

        pos += ray*min(dist, waterDist);
        totDist += min(dist, waterDist);

        if (dist <= 0.001) {
            colour += clamp(textureObj(pos, t)*waterFact - float(iterations)/150., 0., 1.)*.6;
            break;
        } else if (waterDist <= 0.01) {
            waterFact = 0.5;
            vec3 waveDerivative = fbmWave(pos.xz*.1,10, iTime);
            ray = normalize(ray - waveDerivative*0.1 - vec3(0., .1, .0));
            colour = textureWater(waveDerivative, t)*(1.-waterFact) - float(i)/500.;
            checkWater = false;
        } else if (dist >= 100.0) {
            break;
        }
    }

    vec3 finalRay = origin + ray * totDist;
    return clamp(colour, 0.0, 1.0);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // uv made for raymarching
    vec2 uv = (fragCoord *2. - iResolution.xy) / iResolution.y;

    // Camera Definition
    float t = iTime*0.1;
    vec3 origin = vec3(t*3., 0.1, 0.0);
    vec3 ray = normalize(vec3(uv, 7.0));

    // Camera Rotation
    ray.zy *= rot2D(-0.01 + sin(t)*0.01);
    ray.xy *= rot2D(sin(t*3.)*0.03);
    ray.xz *= rot2D((t*smoothstep(1., 5., t))-PI/2.);


    // Time varying pixel color
    vec3 col = raymarch(origin, ray, t);

    // Output to screen
    fragColor = vec4(col,1.0);
}
